 @Test void revokedDuringAcknowledgmentCompensatesAndRetriesHigherVersion()throws Exception{UUID id=submit();approve(id);allocated=new CountDownLatch(1);allowResponse=new CountDownLatch(1);try(var pool=Executors.newSingleThreadExecutor()){var task=pool.submit(()->{try{tick();}catch(Exception e){throw new RuntimeException(e);}});assertTrue(allocated.await(5,TimeUnit.SECONDS));permissions.put(OWNER,Set.of("approval:read"));allowResponse.countDown();task.get();}allocated=null;ticks();assertNotEquals("APPROVED",read(id).get("status").asString(),"permission revoked before APPROVED writeback");assertEquals(false,sources.get("M2/"+id).get("active"),"already acknowledged allocation must be compensated");int released=((Number)sources.get("M2/"+id).get("sourceVersion")).intValue();permissions.put(OWNER,Set.of("approval:read","approval:apply"));CLOCK.instant=CLOCK.instant.plusSeconds(31);ticks();assertEquals("APPROVED",read(id).get("status").asString());assertTrue(((Number)sources.get("M2/"+id).get("sourceVersion")).intValue()>released,"retry advances beyond release tombstone");}
